import { create } from 'zustand';
import resumeService from '@/services/resumeService';
import useAuthStore from './authStore';

const useResumeStore = create((set, get) => ({
  resumeUrl:      null,
  atsReport:      null,
  atsScore:       null,
  parsedResume:   null,
  uploadProgress: 0,
  jobId:          null,
  jobStatus:      'idle', // idle | uploading | parsing | analyzing | complete | failed
  jobMessage:     '',

  setJobProgress: (progress, status, message = '') => {
    const currentStatus = get().jobStatus;
    if (['idle', 'failed', 'complete'].includes(currentStatus)) return;
    set({ uploadProgress: progress, jobStatus: status, jobMessage: message });
  },

  setATSReport: (report, score) =>
    set({ atsReport: report, atsScore: score, jobStatus: 'complete' }),

  setResumeUrl: (url) => set({ resumeUrl: url }),

  setJobId: (jobId) => set({ jobId }),

  reset: () => set({
    uploadProgress: 0,
    jobId:          null,
    jobStatus:      'idle',
    jobMessage:     '',
  }),

  // Upload and start polling
  uploadResume: async (file) => {
    set({ jobStatus: 'uploading', uploadProgress: 0, atsReport: null });
    try {
      const { data } = await resumeService.upload(file, (pct) => {
        set({ uploadProgress: pct });
      });
      set({
        resumeUrl:  data.data.resumeUrl,
        jobId:      data.data.jobId,
        jobStatus:  'parsing',
        jobMessage: 'Resume uploaded. AI analysis starting...',
      });
      return { success: true, jobId: data.data.jobId };
    } catch (err) {
      set({ jobStatus: 'failed', jobMessage: err.response?.data?.message || 'Upload failed' });
      return { success: false, message: err.response?.data?.message || 'Upload failed' };
    }
  },

  // Fetch existing ATS report
  fetchATSReport: async () => {
    try {
      const { data } = await resumeService.getATSReport();
      const d = data.data;
      set({
        resumeUrl:    d.resumeUrl,
        atsScore:     d.atsScore,
        atsReport:    d.atsReport,
        parsedResume: d.parsedResume,
        jobStatus:    d.status === 'complete' ? 'complete' : 'analyzing',
      });
    } catch {}
  },

  // Stop active analysis
  stopAnalysis: async () => {
    // Always reset local state immediately — don't wait for server
    set({
      uploadProgress: 0,
      jobId:          null,
      jobStatus:      'idle',
      jobMessage:     '',
      resumeUrl:      null,
      atsReport:      null,
      atsScore:       null,
      parsedResume:   null,
    });
    // Synchronize changes to authStore
    useAuthStore.getState().updateUser({
      atsScore:     null,
      activeTestId: null,
    });

    try {
      await resumeService.stopAnalysis();
      return { success: true };
    } catch (err) {
      // Even if the server call fails, we already reset local state.
      // Only surface truly unexpected errors (not 404 "nothing to stop").
      const status = err.response?.status;
      if (status === 404 || status === 400) {
        // Nothing was running — that's fine, we already cleared local state
        return { success: true };
      }
      return {
        success: false,
        message: err.response?.data?.message || 'Failed to stop analysis',
      };
    }
  },
}));

export default useResumeStore;
